const { withAppBuildGradle } = require('expo/config-plugins');

/**
 * Signs release builds with this project's own key instead of the debug key.
 *
 * Reads `keystore.properties` from the project root (next to app.json):
 *   storeFile=keystore/release-key.jks   (relative to the project root, or absolute)
 *   storePassword=…
 *   keyAlias=…
 *   keyPassword=…
 *
 * The android/ folder is regenerated by `expo prebuild`, so this lives in a
 * config plugin rather than in android/app/build.gradle directly.
 */
const MARKER = '// @notex/release-signing';

const SETUP = `
${MARKER}
def keystorePropsFile = rootProject.file('../keystore.properties')
def keystoreProps = new Properties()
if (keystorePropsFile.exists()) {
    keystorePropsFile.withInputStream { keystoreProps.load(it) }
}
def releaseStoreFile = { String path ->
    def f = new File(path)
    f.isAbsolute() ? f : rootProject.file("../\${path}")
}
// Fail a release build outright rather than quietly signing it with the debug key.
gradle.taskGraph.whenReady { graph ->
    def releasing = graph.allTasks.any { it.name.toLowerCase().contains('release') }
    if (!releasing) return
    if (!keystorePropsFile.exists()) {
        throw new GradleException("Release signing: \${keystorePropsFile} not found. Copy keystore.properties.example to keystore.properties and fill it in.")
    }
    def missing = ['storeFile', 'storePassword', 'keyAlias', 'keyPassword'].findAll { !keystoreProps[it] }
    if (missing) {
        throw new GradleException("Release signing: keystore.properties is missing \${missing.join(', ')}.")
    }
    if (!releaseStoreFile(keystoreProps['storeFile']).exists()) {
        throw new GradleException("Release signing: keystore file \${releaseStoreFile(keystoreProps['storeFile'])} not found.")
    }
}
`;

const RELEASE_CONFIG = `
        release {
            if (keystoreProps['storeFile']) {
                storeFile releaseStoreFile(keystoreProps['storeFile'])
                storePassword keystoreProps['storePassword']
                keyAlias keystoreProps['keyAlias']
                keyPassword keystoreProps['keyPassword']
            }
        }`;

/** Pure transform of android/app/build.gradle; safe to run more than once. */
function applyReleaseSigning(gradle) {
  if (gradle.includes(MARKER)) return gradle;

  // 1. Load keystore.properties before the android { } block.
  gradle = gradle.replace(/^android \{/m, `${SETUP}\nandroid {`);

  // 2. Add a release signing config after the debug one.
  gradle = gradle.replace(
    /(signingConfigs \{\s*debug \{[^}]*\})/,
    `$1${RELEASE_CONFIG}`,
  );

  // 3. Point the release build type at it.
  gradle = gradle.replace(
    /(buildTypes \{[\s\S]*?release \{[\s\S]*?)signingConfig signingConfigs\.debug/,
    '$1signingConfig signingConfigs.release',
  );

  for (const [check, what] of [
    [MARKER, 'keystore.properties loader'],
    ['signingConfig signingConfigs.release', 'release build type'],
    ["keystoreProps['keyAlias']", 'release signing config'],
  ]) {
    if (!gradle.includes(check)) {
      throw new Error(`withReleaseSigning: could not add the ${what} to android/app/build.gradle.`);
    }
  }
  return gradle;
}

const withReleaseSigning = (config) =>
  withAppBuildGradle(config, (mod) => {
    mod.modResults.contents = applyReleaseSigning(mod.modResults.contents);
    return mod;
  });

module.exports = withReleaseSigning;
module.exports.applyReleaseSigning = applyReleaseSigning;
